w.__LoreInj.getActivePacksForUrl?_w.__LoreInj.getActivePacksForUrl(_url):settings.config.urlPacks?.[_url]||[];const entries=(await db.entries.toArray()).filter(e=>activePacks.includes(e.packName));if(entries.length<2){runStatus.textContent="활성 엔트리 2개 미만.";runStatus.style.color=TONE.danger;return}const embs=await db.embeddings.where("entryId").anyOf(entries.map(e=>e.id)).toArray();const entryById={};entries.forEach(e=>entryById[e.id]=e);const embMap={};for(const eb of embs){if(eb.field!=="summary")continue;const ent=entryById[eb.entryId];if(!ent)continue;if(eb.packName&&eb.packName!==ent.packName)continue;if(C.embeddingSourceHash&&(eb.sourceHash||eb.hash)!==C.embeddingSourceHash(ent,"summary"))continue;embMap[eb.entryId]=eb.vector}const withEmb=entries.filter(e=>embMap[e.id]);if(withEmb.length<2){runStatus.textContent="임베딩 있는 엔트리 2개 미만. 먼저 파일 탭에서 임베딩 생성 필요.";runStatus.style.color=TONE.danger;return}const cos=(a,b)=>{let d=0,na=0,nb=0;const L=Math.min(a.length,b.length);for(let i=0;i<L;i++){d+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i]}return d/(Math.sqrt(na)*Math.sqrt(nb)||1)};const parent={};const find=x=>{let root=x;while(parent[root]!==root)root=parent[root];while(parent[x]!==root){const next=parent[x];parent[x]=root;x=next}return root};const uni=(a,b)=>{parent[find(a)]=find(b)};withEmb.forEach(e=>parent[e.id]=e.id);const pairs=[];for(let i=0;i<withEmb.length;i++){for(let j=i+1;j<withEmb.length;j++){if(!typeCompatible(withEmb[i],withEmb[j]))continue;const s=cos(embMap[withEmb[i].id],embMap[withEmb[j].id]);if(s>=state.threshold){pairs.push({a:withEmb[i].id,b:withEmb[j].id,sim:s});uni(withEmb[i].id,withEmb[j].id)}}}const groupMap={};withEmb.forEach(e=>{const r=find(e.id);(groupMap[r]=groupMap[r]||[]).push(e)});const groups=Object.values(groupMap).filter(g=>g.length>=2).map(g=>{const ids=new Set(g.map(e=>e.id));const maxSim=pairs.filter(p=>ids.has(p.a)&&ids.has(p.b)).reduce((m,p)=>Math.max(m,p.sim),0);return{entries:g,sim:maxSim}}).sort((a,b)=>b.sim-a.sim);state.groups=gr